def min_distance(n, k, rooms):
    free_rooms = [i for i in range(n) if rooms[i] == '0']

    def can_place(john_room, cows):
        last_cow = None
        for _ in range(cows):
            if last_cow is None:
                last_cow = john_room
            else:
                last_cow += 1
                while last_cow < len(free_rooms) and free_rooms[last_cow] - free_rooms[last_cow - 1] <= 1:
                    last_cow += 1
                if last_cow >= len(free_rooms):
                    return False
        return True

    left, right = 0, n
    while left < right:
        mid = (left + right) // 2
        if can_place(free_rooms[mid], k):
            right = mid
        else:
            left = mid + 1

    return left

